import json
import re

BASE = "/Users/kristinarash/Library/Caches/sportsci-batch-98"
IDS = ["Q73", "Q74", "Q75", "Q76", "Q77", "Q78", "Q79", "Q80"]

inputs = {d["id"]: d for d in json.load(open(BASE + "/inputs.json", encoding="utf-8"))}
tax = json.load(open(BASE + "/taxonomy.json", encoding="utf-8"))

problems = []
for i in IDS:
    path = f"{BASE}/drafts/{i}.json"
    d = json.load(open(path, encoding="utf-8"))
    d["sourceFile"] = inputs[i]["sourceFile"]
    json.dump(d, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    # re-read to confirm the file parses
    d = json.load(open(path, encoding="utf-8"))
    if d["id"] != i:
        problems.append(f"{i}: id mismatch")
    if d["sourceFile"] != inputs[i]["sourceFile"]:
        problems.append(f"{i}: sourceFile mismatch")
    if d["decision"] == "EXCLUDE" and not d.get("exclusionReason"):
        problems.append(f"{i}: EXCLUDE without reason")
    if d["decision"] == "DEGRADED" and not d.get("degradedReason"):
        problems.append(f"{i}: DEGRADED without reason")
    if d["decision"] == "INCLUDE":
        p = d["paper"]
        if not p["doi"].startswith("10."):
            problems.append(f"{i}: bad doi")
        if d["primaryDomain"] not in d["domains"]:
            problems.append(f"{i}: primaryDomain not in domains")
        for k in ("studyDesign",):
            if d[k] not in tax["studyDesigns"] and d[k] != "Narrative Review":
                problems.append(f"{i}: {k} not in taxonomy")
        if d["studyDesign"] not in tax["studyDesigns"]:
            problems.append(f"{i}: studyDesign {d['studyDesign']!r} not in taxonomy")
        for v in d["domains"]:
            if v not in tax["domains"]:
                problems.append(f"{i}: domain {v!r} not in taxonomy")
        for v in d["audiences"]:
            if v not in tax["audiences"]:
                problems.append(f"{i}: audience {v!r} not in taxonomy")
        for v in d["sports"]:
            if v not in tax["sports"]:
                problems.append(f"{i}: sport {v!r} not in taxonomy")
        for v in d["populations"]:
            if v not in tax["populations"]:
                problems.append(f"{i}: population {v!r} not in taxonomy")
        for k in ("evidenceSummary", "screeningLimitations", "synthesisCaution"):
            if not d.get(k):
                problems.append(f"{i}: empty {k}")
        if "—" in json.dumps(d, ensure_ascii=False):
            problems.append(f"{i}: em dash present")

print("written:", ", ".join(IDS))
print("problems:", problems if problems else "none")

